insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$perdoes$q$, $q$https://www.diariomunicipal.com.br/amm-mg/materia/00171358 (Lei 3.513/2024, DOM-AMM ed. 3913, 09/12/2024)$q$, $q$Ato oficial de Perdões: domínio público (Lei 9.610/1998, art. 8º, IV). Perímetro urbano aproximado e vias do Centro Histórico: derivados do OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap).$q$, 18, $q$Lei 3.513/2024: proibidos trânsito e estacionamento de veículos pesados, carretas e similares com mais de 3 eixos em todo o perímetro urbano (art. 1º, com exceções de carga e descarga, coletivo, mudanças/obras e garagem) e no Centro Histórico e Cultural (art. 2º, sem a exceção de carga e descarga). Perímetro urbano sem limite oficial: polígono aproximado (BR-381 fora). Centro Histórico: só as vias nomeadas no art. 2º.$q$);
